'use strict';
const APP_VERSION='1.2.0';
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M21 21v-3a6 6 0 0 0-4-5"/>',dumbbell:'<path d="m6 6 12 12M4 9l5-5M2 7l5-5M15 20l5-5M17 22l5-5M5 10l5-5M14 19l5-5"/>',book:'<path d="M12 5v16M3 3h4a5 5 0 0 1 5 2 5 5 0 0 1 5-2h4v16h-4a5 5 0 0 0-5 2 5 5 0 0 0-5-2H3z"/>',chart:'<path d="M4 3v18h17M8 16v-5M13 16V7M18 16v-9"/>',card:'<rect x="2" y="4" width="20" height="16" rx="3"/><path d="M2 10h20M6 15h4"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',activity:'<path d="M2 12h5l3-9 4 18 3-9h5"/>',settings:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2"/>',message:'<path d="M21 11a8 8 0 0 1-8 8H5l-3 3V5a3 3 0 0 1 3-3h8a8 8 0 0 1 8 9zM7 8h9M7 12h6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.activity}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');const today=()=>new Date().toLocaleDateString('en-CA');const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('es-AR',{day:'numeric',month:'short'});
const initials=name=>name.trim().split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase();
const plans=[{id:'inicial',name:'Inicial',limit:10},{id:'profesional',name:'Profesional',limit:30},{id:'equipo',name:'Equipo',limit:null}];
function seed(){return {version:1,coach:{name:'Santiago López',plan:'inicial',email:'',whatsapp:''},coachNotices:[],readCoachNotices:[],students:[{id:'s1',name:'Lucía Martínez',email:'lucia@ejemplo.com',goal:'Ganar fuerza',whatsapp:'',days:3,status:'active',notes:'Entrenamiento progresivo, con foco en la técnica.'},{id:'s2',name:'Martín Pérez',email:'martin@ejemplo.com',goal:'Mejorar resistencia',whatsapp:'',days:4,status:'active',notes:''},{id:'s3',name:'Ana Suárez',email:'ana@ejemplo.com',goal:'Retomar el entrenamiento',whatsapp:'',days:2,status:'active',notes:''}],exercises:[{id:'e1',name:'Sentadilla goblet',group:'Piernas',video:'',notes:'Sostené la carga cerca del pecho y controlá el descenso.'},{id:'e2',name:'Remo con mancuerna',group:'Espalda',video:'',notes:'Mantené la espalda estable y acompañá el recorrido con el codo.'},{id:'e3',name:'Plancha abdominal',group:'Core',video:'',notes:'Sostené la postura. La duración se indica en la rutina.'},{id:'e4',name:'Press de hombros',group:'Hombros',video:'',notes:'Usá una carga que te permita controlar el movimiento.'},{id:'e5',name:'Puente de glúteos',group:'Piernas',video:'',notes:'Apoyá los pies y elevá la cadera de forma controlada.'},{id:'e6',name:'Flexiones de brazos',group:'Pecho',video:'',notes:'Usá la variante acordada con tu profesor.'}],routines:[{id:'r1',name:'Fuerza · Cuerpo completo',description:'Una base para avanzar con constancia.',days:['Lunes','Miércoles','Viernes'],exercises:[{exerciseId:'e1',sets:3,reps:'12',rest:60},{exerciseId:'e2',sets:3,reps:'10 por lado',rest:60},{exerciseId:'e3',sets:3,reps:'30 segundos',rest:45}]},{id:'r2',name:'Volver al movimiento',description:'Movimientos simples para retomar el ritmo.',days:['Martes','Jueves'],exercises:[{exerciseId:'e5',sets:3,reps:'12',rest:60},{exerciseId:'e6',sets:3,reps:'8',rest:60}]}],assignments:[{id:'a1',studentId:'s1',routineId:'r1'},{id:'a2',studentId:'s2',routineId:'r1'},{id:'a3',studentId:'s3',routineId:'r2'}],sessions:[],drafts:{},notices:[{id:'n1',title:'Bienvenidos a Entrenar',body:'Acá vas a encontrar tus rutinas y registrar cada entrenamiento. Avancemos paso a paso.',date:today()}],adminCoaches:[{id:'c1',name:'Santiago López',plan:'inicial',status:'active'}]};}
let state;let storageOK=true;try{const raw=localStorage.getItem('entrenar-v1');state=raw?JSON.parse(raw):seed();if(!state||state.version!==1||!Array.isArray(state.students))state=seed();}catch{state=seed();storageOK=false;}
function upgradeState(){state.coach.email??='';state.coach.whatsapp??='';state.coachNotices??=[];state.readCoachNotices??=[];}
upgradeState();
let role='coach',page='Inicio',studentId=state.students.find(s=>s.status==='active')?.id||'',detailId=null,search='',filter='all',timerEnd=0,timerId=null,deferredPrompt=null;
const $=s=>document.querySelector(s);const main=$('#main');const modal=$('#modal');
function save(){try{localStorage.setItem('entrenar-v1',JSON.stringify(state));return true;}catch{storageOK=false;toast('No se pudo guardar. Exportá una copia antes de cerrar.');return false;}}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>t.classList.remove('visible'),3500);}
const activeStudents=()=>state.students.filter(s=>s.status==='active');const plan=()=>plans.find(p=>p.id===state.coach.plan)||plans[0];const selectedStudent=()=>state.students.find(s=>s.id===studentId);const studentRoutines=sid=>state.assignments.filter(a=>a.studentId===sid).map(a=>state.routines.find(r=>r.id===a.routineId)).filter(Boolean);const sessionsFor=sid=>state.sessions.filter(s=>s.studentId===sid);const getExercise=eid=>state.exercises.find(e=>e.id===eid);
function navItems(){return role==='coach'?[['Inicio','home'],['Alumnos','users'],['Rutinas','dumbbell'],['Ejercicios','book'],['Perfil','users']]:role==='student'?[['Inicio','home'],['Mi rutina','dumbbell'],['Progreso','chart'],['Avisos','message']]:[['Resumen','home'],['Profesores','users'],['Planes','card'],['Comunicados','message'],['Ajustes','settings']];}
const btn=(text,action,cls='primary',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
function heading(kicker,title,subtitle,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function stat(label,value,detail,ic){return `<div class="stat"><div class="stat-top"><span>${label}</span>${icon(ic)}</div><div class="stat-value">${value}</div><div class="stat-detail">${detail}</div></div>`;}
const person=s=>`<div class="person"><span class="avatar">${esc(initials(s.name))}</span><div><h3>${esc(s.name)}</h3><p>${esc(s.goal||s.subtitle||'Profesor')}</p></div></div>`;
const badge=s=>`<span class="badge ${s==='active'?'':s==='pending'?'pending':'neutral'}">${s==='active'?'Activo':s==='pending'?'Pendiente':'Inactivo'}</span>`;
function navigate(next,detail=null){page=next;detailId=detail;search='';filter='all';render();window.scrollTo({top:0,behavior:'instant'});}

const trainingDays=['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
const motivationalPhrases={
 coach:[
  'Tu manera de acompañar puede cambiar la relación de alguien con el entrenamiento.',
  'Cada alumno tiene su ritmo. Escucharlo también es parte de entrenar.',
  'Detrás de cada avance hay alguien que creyó que era posible.',
  'Una buena rutina orienta. Tu acompañamiento marca la diferencia.',
  'Celebrar los pequeños logros también construye grandes hábitos.',
  'Enseñar a disfrutar el proceso es ayudar a sostenerlo.',
  'Hoy podés ayudar a alguien a dar su próximo paso.',
  'La confianza se construye con atención, paciencia y constancia.',
  'Cada persona que acompañás tiene una historia distinta.',
  'Tu compromiso inspira más de lo que imaginás.',
  'El progreso también está en animarse a volver.',
  'Una indicación clara puede hacer más simple el próximo paso.'
 ],
 student:[
  'No necesitás hacerlo perfecto. Cada paso cuenta.',
  'Tu ritmo también es un buen ritmo.',
  'Un entrenamiento a la vez. Un hábito que crece.',
  'Reconocé lo que hoy podés hacer: también es progreso.',
  'La constancia se construye con pasos posibles.',
  'Escucharte y descansar también forman parte del proceso.',
  'El progreso no siempre se ve, pero cada paso cuenta.',
  'Tu recorrido es tuyo. Avanzá sin compararte.',
  'Volver a intentarlo también es un logro.',
  'Hoy podés dar un paso más, a tu manera.',
  'Cada vez que te dedicás tiempo, estás construyendo un hábito.',
  'Disfrutá el proceso y celebrá tus pequeños avances.'
 ]
};
function phraseForDay(forRole,date=new Date()){
 const list=motivationalPhrases[forRole]||motivationalPhrases.student;
 const day=Math.floor(Date.UTC(date.getFullYear(),date.getMonth(),date.getDate())/86400000);
 return list[((day%list.length)+list.length)%list.length];
}
function dailyMotivation(forRole){return `<section class="quote daily-motivation" aria-label="Frase del día"><div class="eyebrow">UN IMPULSO PARA HOY</div><p>“${esc(phraseForDay(forRole))}”</p><small>${forRole==='coach'?'ACOMPAÑÁ CADA PROGRESO':'A TU RITMO, PASO A PASO'}</small></section>`;}
function daysSelector(values){
 const days=values||['Lunes','Miércoles','Viernes'];
 const extras=days.filter(d=>!trainingDays.includes(d));
 return `<div class="field"><label id="days-label">Días de entrenamiento</label><details class="days-picker"><summary aria-labelledby="days-label days-summary"><span id="days-summary">${days.length?days.map(d=>esc(d.slice(0,3))).join(' · '):'Seleccioná los días'}</span><span aria-hidden="true">⌄</span></summary><div class="days-options">${[...trainingDays,...extras].map(d=>`<label class="day-option"><input type="checkbox" name="days" value="${esc(d)}" ${days.includes(d)?'checked':''}><span>${esc(d)}</span></label>`).join('')}</div></details><p class="note-text days-hint">Podés seleccionar más de un día.</p></div>`;
}
function normalizeWhatsapp(value){
 const v=String(value||'').trim();
 if(!/^\+?[\d\s().-]+$/.test(v))return null;
 const digits=v.replace(/\D/g,'');
 return digits.length>=8&&digits.length<=15?(v.startsWith('+')?'+':'')+digits:null;
}

function roleOptions(current){return `<option value="coach" ${current==='coach'?'selected':''}>Profesor</option><option value="student" ${current==='student'?'selected':''}>Alumno</option><option value="admin" ${current==='admin'?'selected':''}>Administrador</option>`;}
function brandMarkup(){return `<button type="button" class="brand-home" data-page="${role==='admin'?'Resumen':'Inicio'}" aria-label="Entrenar · Inicio"><img class="brand-logo" src="/icons/entrenar-logo.svg" width="164" height="36" alt="entrenar."></button>`;}
function renderChrome(){
 const items=navItems();document.body.dataset.role=role;
 const who=role==='coach'?state.coach.name:role==='student'?(selectedStudent()?.name||'Alumno'):'Ramiro Quiroga';
 const label=role==='coach'?'Profesor':role==='student'?'Alumno':'Administrador';
 const nav=items.map(([name,ic])=>`<button type="button" class="nav-btn ${page===name?'active':''}" data-page="${name}" ${page===name?'aria-current="page"':''}>${icon(ic)}<span>${name}</span></button>`).join('');
 $('#sidebar').innerHTML=brandMarkup()+`<div><p class="nav-label">TU ESPACIO</p><nav class="nav-links" aria-label="Navegación principal">${nav}</nav></div><div class="sidebar-bottom"><div class="sidebar-card"><div class="eyebrow">${role==='coach'?'TU PLAN':'PASO A PASO'}</div><h3>${role==='coach'?esc(plan().name):'La constancia cuenta.'}</h3><p>${role==='coach'?activeStudents().length+' alumnos activos · '+(plan().limit?'hasta '+plan().limit:'capacidad a definir'):'Un espacio para acompañar cada progreso.'}</p>${btn(role==='coach'?'Ver mi perfil':'Cómo instalar la app',role==='coach'?'my-profile':'install-help','outline')}</div><div class="version">Versión ${APP_VERSION} · Prueba local</div></div>`;
 const bellPage=role==='coach'?'Notificaciones':role==='student'?'Avisos':'Comunicados';
 const bellLabel=role==='coach'?'Mensajes del administrador':role==='student'?'Avisos de mi profesor':'Comunicados a profesores';
 const unread=role==='coach'?state.coachNotices.some(n=>!state.readCoachNotices.includes(n.id)):role==='student'?state.notices.length>0:false;
 const userChip=role==='coach'?`<button type="button" class="user-chip profile-trigger" data-page="Perfil" aria-label="Abrir perfil de ${esc(who)}"><span class="avatar">${esc(initials(who))}</span><span class="profile-trigger-text"><span class="profile-full-name">${esc(who)}</span><span class="profile-short-name">${esc(who.split(' ')[0])}</span><small>Profesor</small></span></button>`:`<div class="user-chip"><span class="avatar">${esc(initials(who))}</span><div>${esc(who)}<small>${label}</small></div></div>`;
 $('#topbar').innerHTML=`<div class="breadcrumb">Tu espacio <span class="muted">/</span> <strong>${esc(page)}</strong></div><div class="mobile-brand">${brandMarkup()}</div><div class="top-actions"><div class="role-field"><label for="role">Vista de prueba</label><select id="role" aria-label="Elegir vista de prueba">${roleOptions(role)}</select></div><button class="icon-btn" data-page="${bellPage}" aria-label="${bellLabel}">${icon('bell')}${unread?'<span class="dot"></span>':''}</button>${userChip}</div>`;
 $('#mobile-nav').innerHTML=(role==='coach'?items.slice(0,4):items).map(([name,ic])=>`<button type="button" data-page="${name}" class="${page===name?'active':''}" ${page===name?'aria-current="page"':''}>${icon(ic)}${name}</button>`).join('');
}

function render(){renderChrome();if(role==='coach'&&page==='Perfil')return renderCoachProfile();if(role==='coach'&&page==='Notificaciones')return renderCoachInbox();if(role==='admin'&&page==='Comunicados')return renderAdminMessages();if(role==='coach')renderCoach();else if(role==='student')renderStudent();else renderAdmin();}
function studentTable(list,limited=false){if(!list.length)return empty('Todavía no hay alumnos','Agregá tu primer alumno para asignarle una rutina.');return `<div class="table-wrap"><table><thead><tr><th>Alumno</th><th class="hide-mobile">Rutinas</th><th>Estado</th><th><span class="hide-mobile">Ver ficha</span></th></tr></thead><tbody>${list.slice(0,limited?4:999).map(s=>`<tr><td>${person(s)}</td><td class="hide-mobile">${studentRoutines(s.id).length} asignadas</td><td>${badge(s.status)}</td><td><button class="circle-btn" data-action="student-detail" data-id="${esc(s.id)}" aria-label="Ver ficha de ${esc(s.name)}">→</button></td></tr>`).join('')}</tbody></table></div>`;}
function empty(title,desc){return `<div class="empty"><h3>${title}</h3><p>${desc}</p></div>`;}
function week(){const d=new Date();let n=(d.getDay()+6)%7;const start=new Date(d);start.setDate(d.getDate()-n);return `<div class="week">${['L','M','M','J','V','S','D'].map((v,i)=>{const day=new Date(start);day.setDate(start.getDate()+i);return `<div class="day ${i===n?'today':''}">${v}<span>${day.getDate()}</span></div>`;}).join('')}</div>`;}
function renderCoach(){const a=activeStudents();if(page==='Inicio'){const weekAgo=Date.now()-7*86400000;const weekly=state.sessions.filter(s=>new Date(s.completedAt).getTime()>=weekAgo);main.innerHTML='<div class="coach-home-head">'+heading('CONSTRUÍ HÁBITOS, ACOMPAÑÁ PERSONAS',`Hola, ${esc(state.coach.name.split(' ')[0])} <span class="greeting-wave" style="font-weight:400">👋</span>`,'Un nuevo día para acompañar a tus alumnos.',btn(icon('plus')+' Nuevo alumno','new-student'))+'</div>'+`<section class="hero coach-hero"><div><div class="eyebrow">TU TRABAJO HACE LA DIFERENCIA</div><h2>Pequeños pasos.<br>Grandes progresos.</h2><p>Planificá, acompañá y celebrá cada avance.<br>Todo lo que necesitás, en tu espacio.</p></div><div class="hero-art">${icon('dumbbell')}</div><span class="hero-index">MOVIMIENTO / CONSTANCIA / PROGRESO</span></section><div class="grid-stats coach-stats">${stat('Alumnos activos',a.length,'De '+(plan().limit||'capacidad a definir')+' en tu plan','users')}${stat('Rutinas creadas',state.routines.length,'Listas para asignar','dumbbell')}<div class="coach-weekly-stat">${stat('Sesiones esta semana',weekly.length,new Set(weekly.map(s=>s.studentId)).size+' alumnos entrenaron','activity')}</div></div><div class="two-col"><section class="panel"><div class="panel-heading"><h2>Tus alumnos</h2>${btn('Ver todos →','all-students','ghost')}</div>${studentTable(state.students,true)}</section><div><section class="panel"><div class="panel-heading"><h2>Tu semana</h2><span class="muted" style="font-size:11px">${new Date().toLocaleDateString('es-AR',{month:'long'})}</span></div><div class="panel-content">${week()}<div class="mini-card"><h3>Todo empieza con una rutina.</h3><p>Personalizá el entrenamiento según los objetivos de cada alumno.</p>${btn('Ver mis rutinas →','all-routines','ghost')}</div></div></section>${dailyMotivation('coach')}</div></div>`;}
else if(page==='Alumnos'){if(detailId)return renderStudentDetail();main.innerHTML=heading('PERSONAS, OBJETIVOS, PROGRESO','Mis alumnos','Acompañá a cada persona a su ritmo.',btn(icon('plus')+' Nuevo alumno','new-student'))+`<div class="toolbar"><input id="student-search" class="search" type="search" placeholder="Buscar alumno…" aria-label="Buscar alumno" value="${esc(search)}"><select id="student-filter" aria-label="Filtrar alumnos"><option value="all">Todos los alumnos</option><option value="active">Activos</option><option value="inactive">Inactivos</option></select></div><div id="student-list" class="cards"></div>`;renderStudentList();}
else if(page==='Rutinas'){main.innerHTML=heading('PLANIFICAR PARA AVANZAR','Mis rutinas','Creá plantillas y adaptalas a tus alumnos.',btn(icon('plus')+' Crear rutina','new-routine'))+`<div class="cards">${state.routines.map(r=>`<article class="routine-card"><span class="badge neutral">${r.exercises.length} ejercicios</span><div class="eyebrow">${esc(r.days.join(' · ')||'Días a definir')}</div><h3>${esc(r.name)}</h3><p>${esc(r.description||'Rutina personalizada.')}</p><div class="row"><span class="note-text">${state.assignments.filter(a=>a.routineId===r.id).length} alumnos</span>${btn('Editar','edit-routine','ghost',`data-id="${esc(r.id)}"`)}</div>${btn('Asignar a un alumno '+icon('arrow'),'assign-routine','outline',`data-id="${esc(r.id)}"`)}</article>`).join('')}</div>${state.routines.length?'':empty('Tu primera rutina empieza acá','Creá una rutina con ejercicios, series y descansos.')}`;}
else if(page==='Ejercicios'){main.innerHTML=heading('TU BIBLIOTECA DE MOVIMIENTO','Ejercicios','Tu catálogo, con indicaciones y videos propios.',btn(icon('plus')+' Nuevo ejercicio','new-exercise'))+`<div class="toolbar"><input class="search" type="search" id="exercise-search" aria-label="Buscar ejercicio" placeholder="Buscar ejercicio…"></div><div id="exercise-list" class="cards"></div>`;renderExerciseList();}
else if(page==='Mi plan'){main.innerHTML=heading('CRECÉ A TU RITMO','Tu suscripción','Un abono mensual según tus alumnos activos.')+`<section class="detail-header"><div class="row"><div><span class="eyebrow">PLAN ACTUAL · ${esc(plan().name)}</span><h2>${a.length} alumnos activos${plan().limit?' de '+plan().limit:''}</h2></div><span class="badge">Suscripción de prueba</span></div><div class="progress"><span style="width:${plan().limit?Math.min(100,a.length/plan().limit*100):0}%"></span></div><p class="note-text">Los alumnos inactivos conservan su historial y no ocupan cupo.</p></section>${planCards(false)}<div class="subtle">Precios por definir. Esta versión permite probar los planes sin realizar cobros.</div>`;}
else if(page==='Avisos')renderNotices(true);}
function renderStudentList(){const list=state.students.filter(s=>(s.name+' '+s.goal).toLowerCase().includes(search.toLowerCase())&&(filter==='all'||s.status===filter));$('#student-list').innerHTML=list.map(s=>`<article class="student-card"><div class="row">${person(s)}${badge(s.status)}</div><p>${s.days} días por semana</p><p>${studentRoutines(s.id).length} rutinas · ${sessionsFor(s.id).length} sesiones completadas</p>${btn('Ver ficha '+icon('arrow'),'student-detail','outline full',`data-id="${esc(s.id)}"`)}</article>`).join('')||empty('No encontramos alumnos','Probá otro nombre o cambiá el filtro.');}
function renderStudentDetail(){const s=state.students.find(x=>x.id===detailId);if(!s){detailId=null;return renderCoach();}const routines=studentRoutines(s.id);const sessions=sessionsFor(s.id);main.innerHTML=btn(icon('back')+' Mis alumnos','all-students','ghost')+heading('FICHA DEL ALUMNO',esc(s.name),esc(s.goal),btn('Editar ficha','edit-student','outline',`data-id="${esc(s.id)}"`))+`<div class="detail-header"><div class="row">${person(s)}${badge(s.status)}</div><p class="note-text" style="margin-top:15px">${esc(s.email||'Sin correo registrado')} · ${s.days} días por semana</p>${s.whatsapp?`<p class="note-text" style="margin-top:12px">WhatsApp: <a class="contact-link" href="https://wa.me/${esc(s.whatsapp.replace(/\D/g,''))}" target="_blank" rel="noopener noreferrer">${esc(s.whatsapp)} ↗</a></p>`:''}${s.notes?`<p class="note-text" style="margin-top:12px">${esc(s.notes)}</p>`:''}</div><div class="two-col"><section class="panel"><div class="panel-heading"><h2>Rutinas asignadas</h2>${btn('Asignar rutina','assign-to-student','ghost',`data-id="${esc(s.id)}"`)}</div><div class="panel-content">${routines.map(r=>`<div class="list-item"><h3>${esc(r.name)}</h3><p class="note-text">${esc(r.days.join(' · '))} · ${r.exercises.length} ejercicios</p>${btn('Quitar asignación','unassign','ghost',`data-sid="${esc(s.id)}" data-id="${esc(r.id)}"`)}</div>`).join('')||empty('Sin rutinas asignadas','Asignale una para que pueda empezar.')}</div></section><section class="panel"><div class="panel-heading"><h2>Últimos entrenamientos</h2></div><div class="panel-content">${sessionList(sessions)}</div></section></div><div style="margin-top:22px">${btn(s.status==='active'?'Pasar a inactivo':'Reactivar alumno','toggle-student','outline',`data-id="${esc(s.id)}"`)}</div>`;}
function renderExerciseList(){const list=state.exercises.filter(e=>(e.name+' '+e.group).toLowerCase().includes(search.toLowerCase()));$('#exercise-list').innerHTML=list.map(e=>`<article class="routine-card"><span class="badge neutral">${esc(e.group)}</span><h3 style="margin-top:17px">${esc(e.name)}</h3><p>${esc(e.notes||'Sin indicaciones adicionales.')}</p><div class="btns">${btn('Editar','edit-exercise','outline',`data-id="${esc(e.id)}"`)}${e.video?`<a class="btn outline" href="${esc(safeUrl(e.video))}" target="_blank" rel="noopener noreferrer">Ver video ↗</a>`:''}</div></article>`).join('')||empty('Sin resultados','Probá buscar otro ejercicio.');}
function safeUrl(v){try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:'#';}catch{return '#';}}

function noticeCards(list){return list.map(n=>`<article class="notice"><div class="row"><h3>${esc(n.title)}</h3><small>${dateLabel(n.date)}</small></div><p style="white-space:pre-wrap">${esc(n.body)}</p></article>`).join('');}
function renderCoachProfile(){
 const c=state.coach;const current=plan();const active=activeStudents().length;
 main.innerHTML=heading('TU ESPACIO PERSONAL','Mi perfil','Tus datos, tu plan y la comunicación con tus alumnos.',btn('Editar datos','edit-coach-profile','outline'))+`
 <section class="profile-card"><div class="profile-intro"><span class="avatar profile-avatar">${esc(initials(c.name))}</span><div><h2>${esc(c.name)}</h2><p class="note-text">Profesor · Entrenar</p></div></div><div class="profile-contacts"><div><span class="eyebrow">CORREO</span><p>${esc(c.email||'Sin completar')}</p></div><div><span class="eyebrow">WHATSAPP</span><p>${esc(c.whatsapp||'Sin completar')}</p></div></div></section>
 <div class="two-col"><div class="stack"><section class="panel"><div class="panel-heading"><h2>Mi plan</h2><span class="badge">${esc(current.name)}</span></div><div class="panel-content"><div class="row"><p class="note-text">Alumnos activos</p><strong>${active}${current.limit?' / '+current.limit:''}</strong></div><div class="progress"><span style="width:${current.limit?Math.min(100,active/current.limit*100):0}%"></span></div><p class="note-text">Estado: plan de prueba · Precio por definir.</p><p class="note-text">Vencimiento: todavía no configurado.</p><div style="margin-top:17px">${btn('Consultar planes','my-plan','outline full')}</div></div></section>
 <section class="panel"><div class="panel-heading"><h2>Vista de prueba</h2></div><div class="panel-content"><label for="profile-role">Cambiar vista</label><select id="profile-role">${roleOptions(role)}</select></div></section></div>
 <section class="panel"><div class="panel-heading"><h2>Avisos a mis alumnos</h2><span class="badge neutral">${state.notices.length}</span></div><div class="panel-content"><p class="note-text">Compartí novedades con todos tus alumnos. Las verán en su campanita.</p><div style="margin:17px 0 8px">${btn(icon('message')+' Enviar aviso a mis alumnos','new-notice','primary full')}</div><p class="note-text">Esta prueba guarda los avisos en este navegador.</p></div>${noticeCards(state.notices.slice(0,4))||empty('Todavía no enviaste avisos','Los mensajes publicados quedarán en este espacio.')}</section></div>`;
}
function renderCoachInbox(){
 const unread=state.coachNotices.filter(n=>!state.readCoachNotices.includes(n.id));
 main.innerHTML=heading('COMUNICACIÓN DE LA PLATAFORMA','Mis notificaciones','Mensajes que recibís del administrador de Entrenar.',unread.length?btn('Marcar como leídos','read-coach-notices','outline'):'')+`<section class="panel"><div class="panel-heading"><h2>Administración de Entrenar</h2><span class="badge neutral">${unread.length} sin leer</span></div>${state.coachNotices.map(n=>`<article class="notice"><div class="row"><h3>${esc(n.title)}</h3>${!state.readCoachNotices.includes(n.id)?'<span class="badge">Nuevo</span>':''}</div><p style="white-space:pre-wrap">${esc(n.body)}</p><small>${dateLabel(n.date)}</small></article>`).join('')||empty('Estás al día','Los mensajes del administrador van a aparecer acá.')}</section>`;
}
function renderAdminMessages(){
 main.innerHTML=heading('COMUNICACIÓN CON LOS PROFESORES','Comunicados','Novedades que aparecerán en la campanita de los profesores.',btn(icon('plus')+' Nuevo comunicado','new-admin-notice'))+`<section class="panel"><div class="panel-heading"><h2>Comunicados publicados</h2><span class="badge neutral">${state.coachNotices.length}</span></div>${noticeCards(state.coachNotices)||empty('Todavía no hay comunicados','Publicá el primero para probar la campanita del profesor.')}</section><div class="subtle">Demostración local: los comunicados se ven al cambiar a la vista Profesor en este navegador. La entrega entre dispositivos se conectará con la base de datos.</div>`;
}
function noticeForm(audience){
 const forStudents=audience==='students';const count=forStudents?state.students.length:state.adminCoaches.length;
 const title=forStudents?'Aviso para mis alumnos':'Comunicado a profesores';
 openModal(title,forStudents?'Aparecerá en la campanita de tus alumnos.':'Aparecerá en la campanita de los profesores.',`<form id="broadcast-form" data-audience="${audience}">${field('Título','title','','text','required maxlength="100"')}<div class="field"><label for="broadcast-body">Mensaje</label><textarea id="broadcast-body" name="body" required maxlength="2000"></textarea></div><p class="note-text">Destinatarios: ${count} ${forStudents?'alumnos':'profesores'} de prueba. No se envían mensajes externos.</p>${actions('Revisar aviso')}</form>`);
}
function coachProfileForm(){
 const c=state.coach;
 openModal('Editar mis datos','Tu nombre se actualizará también en el encabezado.',`<form id="coach-profile-form">${field('Nombre y apellido','name',c.name,'text','required maxlength="80" autocomplete="off"')}${field('Correo (opcional)','email',c.email,'email','maxlength="160" autocomplete="off"')}${field('WhatsApp (opcional, con código de país)','whatsapp',c.whatsapp,'tel','inputmode="tel" maxlength="25" placeholder="+54 9 11 2345 6789" autocomplete="off"')}${actions('Guardar mis datos')}</form>`);
}

function renderNotices(coach=false){main.innerHTML=heading('SEGUIMOS EN CONTACTO',coach?'Avisos para tus alumnos':'Avisos de tu profe',coach?'Compartí novedades con todos tus alumnos.':'Indicaciones y novedades para acompañarte.',coach?btn(icon('plus')+' Publicar aviso','new-notice'):'')+`<section class="panel"><div class="panel-heading"><h2>${esc(state.coach.name)}</h2><span class="badge neutral">${state.notices.length} avisos</span></div>${state.notices.map(n=>`<article class="notice"><h3>${esc(n.title)}</h3><p style="white-space:pre-wrap">${esc(n.body)}</p><small>${dateLabel(n.date)}</small></article>`).join('')||empty('Sin avisos por ahora','Las novedades aparecerán acá.')}</section>`;}
function studentPicker(){return `<div class="toolbar"><label class="note-text" for="student-select">Alumno de prueba</label><select id="student-select" aria-label="Alumno de prueba">${state.students.map(s=>`<option value="${esc(s.id)}" ${studentId===s.id?'selected':''}>${esc(s.name)}${s.status!=='active'?' · Inactivo':''}</option>`).join('')}</select></div>`;}
function renderStudent(){const s=selectedStudent();if(!s){main.innerHTML=heading('TU ENTRENAMIENTO','Todavía no hay alumnos','Cargá un alumno desde la vista Profesor para probar su experiencia.');return;}const sessions=sessionsFor(s.id);const routines=studentRoutines(s.id);if(page==='Avisos'){renderNotices(false);return;}if(s.status!=='active'){main.innerHTML=heading('TU ENTRENAMIENTO',esc(s.name),'Tu ficha está inactiva.')+studentPicker()+`<section class="panel">${empty('Entrenamientos en pausa','Tu historial se conserva. El profesor puede reactivar tu ficha.')}</section>`;return;}
if(page==='Inicio'){main.innerHTML=heading('TU PRÓXIMO PASO EMPIEZA HOY',`Vamos, ${esc(s.name.split(' ')[0])}.`,'Tu entrenamiento, a tu ritmo.')+studentPicker()+`<section class="hero"><div><div class="eyebrow">TU PROFE · ${esc(state.coach.name)}</div><h2>${routines.length?'Hoy también cuenta.':'Listo para empezar.'}</h2><p>${routines.length?esc(routines[0].name)+' · '+routines[0].exercises.length+' ejercicios':'Tu profesor te asignará una rutina para comenzar.'}</p>${btn('Ver mi entrenamiento '+icon('arrow'),'student-routines','lime')}</div><div class="hero-art">${icon('activity')}</div><span class="hero-index">TU RITMO. TU PROGRESO.</span></section><div class="grid-stats">${stat('Sesiones realizadas',sessions.length,'Tu constancia, registrada','check')}${stat('Rutinas asignadas',routines.length,'Preparadas para vos','dumbbell')}${stat('Objetivo semanal',s.days,'Días de entrenamiento','activity')}</div><div class="two-col"><section class="panel"><div class="panel-heading"><h2>Tus últimos pasos</h2>${btn('Ver progreso →','student-progress','ghost')}</div><div class="panel-content">${sessionList(sessions)}</div></section><div><section class="panel"><div class="panel-heading"><h2>Tu semana</h2></div><div class="panel-content">${week()}<div class="mini-card"><h3>${esc(s.goal)}</h3><p>Un entrenamiento a la vez. Tu profesor acompaña cada avance.</p></div></div></section>${dailyMotivation('student')}</div></div>`;}
else if(page==='Mi rutina'){if(detailId){const r=routines.find(x=>x.id===detailId);if(r)return renderWorkout(s,r);detailId=null;}main.innerHTML=heading('HECHO PARA VOS','Mis entrenamientos','Elegí una rutina para empezar.')+studentPicker()+`<div class="cards">${routines.map(r=>`<article class="routine-card"><span class="badge neutral">${r.exercises.length} ejercicios</span><div class="eyebrow">${esc(r.days.join(' · '))}</div><h3>${esc(r.name)}</h3><p>${esc(r.description)}</p>${btn('Comenzar entrenamiento '+icon('arrow'),'start-workout','primary',`data-id="${esc(r.id)}"`)}</article>`).join('')}</div>${routines.length?'':empty('Tu rutina está en camino','El profesor todavía no te asignó entrenamientos.')}`;}
else if(page==='Progreso'){const weeks=Array.from({length:4},(_,i)=>{const end=Date.now()-(3-i)*7*86400000;const start=end-7*86400000;return sessions.filter(x=>{const d=new Date(x.completedAt).getTime();return d>start&&d<=end;}).length;});main.innerHTML=heading('CADA PASO QUEDA REGISTRADO','Tu progreso','Tu recorrido, entrenamiento a entrenamiento.')+studentPicker()+`<div class="grid-stats">${stat('Sesiones completadas',sessions.length,'Desde tu primer entrenamiento','check')}${stat('Esta semana',weeks[3],s.days+' días como objetivo','activity')}${stat('Última sesión',sessions.length?dateLabel(sessions[0].date):'—',sessions.length?'Seguí construyendo el hábito':'Tu primer paso te espera','clock')}</div><div class="two-col"><section class="panel"><div class="panel-heading"><h2>Sesiones por semana</h2></div><div class="panel-content"><div class="trend-bars" role="img" aria-label="Sesiones de las últimas cuatro semanas: ${weeks.join(', ')}">${weeks.map((n,i)=>`<div class="trend-column"><span>${n}</span><div class="bar" style="height:${Math.max(3,n/Math.max(1,...weeks)*100)}px"></div><span>${i===3?'Actual':'Hace '+(3-i)+' sem.'}</span></div>`).join('')}</div></div></section><section class="panel"><div class="panel-heading"><h2>Historial</h2></div><div class="panel-content">${sessionList(sessions,true)}</div></section></div>`;}}
function sessionList(list,detail=false){return list.length?list.slice(0,10).map(s=>`<div class="list-item"><div class="row"><h3>${esc(s.routineName)}</h3><span class="badge">Completado</span></div><p class="note-text">${dateLabel(s.date)} · ${s.exercises.length} ejercicios</p>${detail?s.exercises.map(e=>`<p class="note-text">${esc(e.name)}${e.load!==''?' · '+esc(e.load)+' kg':''}${e.actualReps?' · '+esc(e.actualReps)+' reps/seg':''}</p>`).join(''):''}${s.note?`<p class="note-text">${esc(s.note)}</p>`:''}</div>`).join(''):empty('Tu historia empieza acá','Los entrenamientos completados aparecerán en este espacio.');}
function draftKey(sid,rid){return sid+':'+rid;}
function renderWorkout(s,r){const key=draftKey(s.id,r.id);const draft=state.drafts[key]||{done:[],logs:{},note:''};const count=r.exercises.filter((_,i)=>draft.done.includes(i)).length;main.innerHTML=btn(icon('back')+' Mis entrenamientos','student-routines','ghost')+heading('TU SESIÓN DE HOY',esc(r.name),count+' de '+r.exercises.length+' ejercicios completados')+`<section class="panel"><div class="panel-heading"><h2>${esc(s.name)}</h2><span class="badge neutral">${esc(r.days.join(' · '))}</span></div><div class="panel-content"><div class="progress"><span style="width:${count/r.exercises.length*100}%"></span></div></div>${r.exercises.map((x,i)=>{const e=getExercise(x.exerciseId);const log=draft.logs[i]||{};return `<div class="exercise-row"><span class="exercise-index">${String(i+1).padStart(2,'0')}</span><div class="exercise-info"><h3>${esc(e?.name||'Ejercicio')}</h3><p>${x.sets} series × ${esc(x.reps)} · ${x.rest} s de descanso</p>${e?.notes?`<p>${esc(e.notes)}</p>`:''}<div class="btns">${btn(icon('clock')+' Descansar','rest','ghost',`data-seconds="${x.rest}"`)}${e?.video?`<a class="btn ghost" href="${esc(safeUrl(e.video))}" target="_blank" rel="noopener noreferrer">Ver video ↗</a>`:''}</div></div><button class="check ${draft.done.includes(i)?'done':''}" data-action="toggle-exercise" data-index="${i}" data-rid="${esc(r.id)}" aria-label="Marcar ${esc(e?.name)} como ${draft.done.includes(i)?'pendiente':'completado'}" aria-pressed="${draft.done.includes(i)}">${draft.done.includes(i)?'✓':'○'}</button></div><div class="exercise-log"><div><label for="load-${i}">Carga (kg), opcional</label><input type="number" min="0" max="1000" step="0.5" inputmode="decimal" id="load-${i}" data-log="load" data-index="${i}" data-rid="${esc(r.id)}" value="${esc(log.load??'')}" placeholder="Ej.: 10"></div><div><label for="reps-${i}">Reps / segundos reales</label><input type="text" maxlength="40" id="reps-${i}" data-log="actualReps" data-index="${i}" data-rid="${esc(r.id)}" value="${esc(log.actualReps??'')}" placeholder="Ej.: 12"></div></div>`;}).join('')}<div class="timer" id="timer-panel"><div><strong id="timer-value">${timerEnd?timerText():'00:00'}</strong><p>Descanso entre series</p></div>${btn('Detener','stop-rest','outline')}</div><div class="panel-content" style="padding-top:22px"><label for="workout-note">¿Cómo te sentiste? (opcional)</label><textarea id="workout-note" data-rid="${esc(r.id)}" maxlength="1000" placeholder="Dejá una observación para tu profe…">${esc(draft.note)}</textarea><div style="margin-top:18px">${btn('Finalizar entrenamiento '+icon('check'),'finish-workout','primary full',`data-id="${esc(r.id)}" ${count!==r.exercises.length?'disabled':''}`)}</div><p class="note-text" style="margin-top:12px">Marcá todos los ejercicios para guardar la sesión. Si salís, tu avance queda guardado en este navegador.</p></div></section>`;}
function planCards(admin){return `<div class="cards">${plans.map((p,i)=>`<article class="plan-card ${(!admin&&plan().id===p.id)?'featured':''}"><span class="badge ${i===1?'':'neutral'}">${!admin&&plan().id===p.id?'Tu plan actual':i===1?'Para crecer':'ABONO MENSUAL'}</span><h3>${p.name}</h3><p>${p.limit?'Hasta '+p.limit+' alumnos activos':'Equipos y más de 30 alumnos'}</p><ul><li>Rutinas personalizadas</li><li>Biblioteca de ejercicios</li><li>Seguimiento y progreso</li><li>Avisos para tus alumnos</li></ul><h2>Precio por definir</h2>${!admin?btn(plan().id===p.id?'Plan seleccionado':'Probar este plan','select-plan',plan().id===p.id?'lime':'outline',`data-id="${p.id}" ${plan().id===p.id?'disabled':''}`):''}</article>`).join('')}</div>`;}
function renderAdmin(){const coaches=state.adminCoaches;if(page==='Resumen'){main.innerHTML=heading('VISTA GENERAL','Tu plataforma','Gestioná profesores, planes y suscripciones.')+`<section class="hero"><div><div class="eyebrow">TU MODELO DE NEGOCIO</div><h2>El profesor crece.<br>Tu plataforma también.</h2><p>Un abono mensual por profesor, según sus alumnos activos.</p>${btn('Ver planes '+icon('arrow'),'admin-plans','lime')}</div><div class="hero-art">${icon('chart')}</div></section><div class="grid-stats">${stat('Profesores',coaches.length,'Registrados en esta prueba','users')}${stat('Alumnos activos',activeStudents().length,'Del profesor de demostración','activity')}${stat('Cobros reales','—','Se conectarán más adelante','card')}</div><section class="panel"><div class="panel-heading"><h2>Profesores registrados</h2>${btn('Administrar →','admin-coaches','ghost')}</div>${coachTable()}</section>`;}
else if(page==='Profesores'){main.innerHTML=heading('ACOMPAÑÁ A QUIENES ACOMPAÑAN','Profesores','Administración local de suscripciones de prueba.',btn(icon('plus')+' Nuevo profesor','new-coach'))+`<section class="panel">${coachTable()}</section><div class="subtle">Los profesores adicionales son registros administrativos de prueba. La vinculación de sus cuentas y alumnos se incorporará al conectar la base de datos.</div>`;}
else if(page==='Planes')main.innerHTML=heading('UN MODELO SIMPLE','Planes de la plataforma','El profesor abona por capacidad de alumnos activos.')+planCards(true)+`<div class="subtle">Los precios y el medio de cobro se definirán antes del lanzamiento. No se procesan pagos en esta versión.</div>`;
else if(page==='Ajustes')main.innerHTML=heading('TU INFORMACIÓN, A MANO','Ajustes de prueba','Conservá una copia de lo que estás probando.')+`<div class="two-col"><section class="panel"><div class="panel-heading"><h2>Copia de seguridad</h2></div><div class="panel-content"><p class="note-text">Descargá alumnos, rutinas e historial para conservarlos o llevarlos a otro navegador. Al importar, se reemplazan los datos locales actuales.</p><div class="btns" style="margin-top:18px">${btn(icon('download')+' Exportar datos','export','primary')}${btn('Importar copia','import','outline')}</div><input type="file" id="import-file" accept="application/json,.json" hidden></div></section><section class="panel"><div class="panel-heading"><h2>Perfil del profesor de prueba</h2></div><div class="panel-content"><p class="note-text">${esc(state.coach.name)}</p>${btn('Editar nombre','coach-name','ghost')}<hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><p class="note-text">Podés volver a los datos de ejemplo. Se eliminarán los cambios guardados en este navegador.</p><div style="margin-top:15px">${btn('Restablecer prueba','reset','danger')}</div></div></section></div><div class="subtle">Guardado local: ${storageOK?'disponible':'no disponible'}. Las vistas de prueba no son cuentas con autenticación. Los datos todavía no se sincronizan entre dispositivos.</div>`;}
function coachTable(){return `<div class="table-wrap"><table><thead><tr><th>Profesor</th><th>Plan</th><th>Estado</th><th>Editar</th></tr></thead><tbody>${state.adminCoaches.map(c=>`<tr><td>${person({name:c.name,subtitle:'Profesor de prueba'})}</td><td>${esc(plans.find(p=>p.id===c.plan)?.name||'Inicial')}</td><td>${badge(c.status)}</td><td>${btn('Editar','edit-coach','ghost',`data-id="${esc(c.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`;}
function openModal(title,subtitle,content){$('#modal-body').innerHTML=`<div class="modal-head"><div><h2>${title}</h2><p>${subtitle}</p></div><button type="button" data-action="close-modal" aria-label="Cerrar">×</button></div><div class="modal-content">${content}</div>`;if(!modal.open)modal.showModal();}
const field=(label,name,value='',type='text',extra='')=>`<div class="field"><label for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const errorSlot='<div class="error-message" role="alert" id="form-error"></div>';
function actions(text){return `${errorSlot}<div class="form-actions">${btn('Cancelar','close-modal','outline')}<button type="submit" class="btn primary">${text}</button></div>`;}
function studentForm(s){openModal(s?'Editar alumno':'Nuevo alumno','Un objetivo personal. Un entrenamiento a su medida.',`<form id="student-form" data-id="${esc(s?.id||'')}">${field('Nombre y apellido','name',s?.name||'','text','required maxlength="80" autocomplete="off"')}${field('WhatsApp (con código de país)','whatsapp',s?.whatsapp||'','tel','required inputmode="tel" autocomplete="off" maxlength="25" placeholder="Ej.: +54 9 11 2345 6789"')}${field('Correo (opcional)','email',s?.email||'','email','maxlength="160" autocomplete="off"')}${field('Objetivo','goal',s?.goal||'','text','required maxlength="120"')}${field('Días por semana','days',s?.days||3,'number','required min="1" max="7" inputmode="numeric"')}<div class="field"><label for="field-notes">Observaciones (opcional)</label><textarea id="field-notes" name="notes" maxlength="1000">${esc(s?.notes||'')}</textarea></div>${actions('Guardar alumno')}</form>`);}
function exerciseForm(e){openModal(e?'Editar ejercicio':'Nuevo ejercicio','Sumá tus indicaciones y un enlace a tu video.',`<form id="exercise-form" data-id="${esc(e?.id||'')}">${field('Nombre del ejercicio','name',e?.name||'','text','required maxlength="100"')}<div class="field"><label for="field-group">Grupo muscular</label><select name="group" id="field-group">${['Piernas','Espalda','Pecho','Hombros','Brazos','Core','Movilidad','Cardio'].map(g=>`<option ${e?.group===g?'selected':''}>${g}</option>`).join('')}</select></div>${field('Enlace al video (opcional)','video',e?.video||'','url','placeholder="https://…" maxlength="1500"')}<div class="field"><label for="field-notes">Indicaciones (opcional)</label><textarea id="field-notes" name="notes" maxlength="1000">${esc(e?.notes||'')}</textarea></div>${actions('Guardar ejercicio')}</form>`);}
function exerciseEditor(x={}){return `<div class="exercise-editor"><div class="row"><select aria-label="Ejercicio" name="exerciseId" required>${state.exercises.map(e=>`<option value="${esc(e.id)}" ${e.id===x.exerciseId?'selected':''}>${esc(e.name)}</option>`).join('')}</select><button type="button" class="remove-exercise" data-action="remove-editor" aria-label="Quitar ejercicio">×</button></div><div class="form-grid"><div><label>Series<input name="sets" type="number" min="1" max="30" required value="${x.sets||3}"></label></div><div><label>Reps / duración<input name="reps" maxlength="40" required value="${esc(x.reps||'12')}"></label></div><div><label>Descanso (s)<input name="rest" type="number" min="0" max="600" required value="${x.rest??60}"></label></div></div></div>`;}
function routineForm(r){if(!state.exercises.length){toast('Primero agregá un ejercicio a tu biblioteca.');return;}openModal(r?'Editar rutina':'Crear rutina',r?'Los cambios se aplican a todos sus alumnos asignados y reinician sus sesiones pendientes. El historial finalizado se conserva.':'Diseñá un entrenamiento que puedan hacer suyo.',`<form id="routine-form" data-id="${esc(r?.id||'')}">${field('Nombre de la rutina','name',r?.name||'','text','required maxlength="100"')}${field('Descripción (opcional)','description',r?.description||'','text','maxlength="250"')}${daysSelector(r?.days)}<label>Ejercicios</label><div id="routine-exercises">${(r?.exercises||[{}]).map(exerciseEditor).join('')}</div>${btn(icon('plus')+' Agregar ejercicio','add-editor','outline')}${actions('Guardar rutina')}</form>`);}
function assignmentForm(rid,sid){if(!activeStudents().length||!state.routines.length){toast('Necesitás un alumno activo y una rutina para asignar.');return;}openModal('Asignar rutina','El alumno podrá verla desde su espacio de entrenamiento.',`<form id="assign-form"><div class="field"><label for="assign-student">Alumno</label><select id="assign-student" name="studentId">${activeStudents().map(s=>`<option value="${esc(s.id)}" ${s.id===sid?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label for="assign-routine">Rutina</label><select id="assign-routine" name="routineId">${state.routines.map(r=>`<option value="${esc(r.id)}" ${r.id===rid?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div>${actions('Asignar rutina')}</form>`);}
function coachForm(c){openModal(c?'Editar profesor':'Nuevo profesor','Registro administrativo de prueba.',`<form id="coach-form" data-id="${esc(c?.id||'')}">${field('Nombre y apellido','name',c?.name||'','text','required maxlength="80"')}<div class="field"><label for="coach-plan">Plan</label><select name="plan" id="coach-plan">${plans.map(p=>`<option value="${p.id}" ${c?.plan===p.id?'selected':''}>${p.name}</option>`).join('')}</select></div><div class="field"><label for="coach-status">Estado</label><select name="status" id="coach-status">${[['active','Activo'],['pending','Pendiente'],['inactive','Inactivo']].map(([v,n])=>`<option value="${v}" ${c?.status===v?'selected':''}>${n}</option>`).join('')}</select></div>${actions('Guardar profesor')}</form>`);}
function ensureDraft(rid){const key=draftKey(studentId,rid);if(!state.drafts[key])state.drafts[key]={done:[],logs:{},note:''};return state.drafts[key];}
function timerText(){const left=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));return String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0');}
function stopTimer(){timerEnd=0;clearInterval(timerId);timerId=null;const el=$('#timer-value');if(el)el.textContent='00:00';}
function startTimer(seconds){stopTimer();if(seconds<=0){toast('Este ejercicio no tiene descanso programado.');return;}timerEnd=Date.now()+seconds*1000;const tick=()=>{const el=$('#timer-value');if(el)el.textContent=timerText();if(Date.now()>=timerEnd){stopTimer();toast('Descanso terminado. Seguí a tu ritmo.');}};tick();timerId=setInterval(tick,500);}
const confirmModal=(title,message,action,attrs='')=>openModal(title,'',`<p class="note-text">${message}</p><div class="form-actions">${btn('Cancelar','close-modal','outline')}${btn('Confirmar',action,'primary',attrs)}</div>`);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-page]');if(!b)return;if(b.dataset.page){navigate(b.dataset.page);return;}const a=b.dataset.action;const itemId=b.dataset.id;if(a==='close-modal'){modal.close();return;}if(a==='new-student')return studentForm();if(a==='edit-student')return studentForm(state.students.find(s=>s.id===itemId));if(a==='student-detail')return navigate('Alumnos',itemId);if(a==='all-students')return navigate('Alumnos');if(a==='all-routines')return navigate('Rutinas');if(a==='my-plan')return navigate('Mi plan');if(a==='student-routines')return navigate('Mi rutina');if(a==='student-progress')return navigate('Progreso');if(a==='new-exercise')return exerciseForm();if(a==='edit-exercise')return exerciseForm(getExercise(itemId));if(a==='new-routine')return routineForm();if(a==='edit-routine')return routineForm(state.routines.find(r=>r.id===itemId));if(a==='add-editor'){$('#routine-exercises').insertAdjacentHTML('beforeend',exerciseEditor());return;}if(a==='remove-editor'){if(document.querySelectorAll('.exercise-editor').length<2){toast('La rutina necesita al menos un ejercicio.');return;}b.closest('.exercise-editor').remove();return;}if(a==='assign-routine')return assignmentForm(itemId);if(a==='assign-to-student')return assignmentForm(null,itemId);if(a==='unassign')return confirmModal('Quitar asignación','El historial de sesiones del alumno se conserva.','confirm-unassign',`data-id="${esc(itemId)}" data-sid="${esc(b.dataset.sid)}"`);if(a==='confirm-unassign'){state.assignments=state.assignments.filter(x=>!(x.routineId===itemId&&x.studentId===b.dataset.sid));save();modal.close();render();toast('Asignación quitada.');return;}
if(a==='toggle-student'){const s=state.students.find(x=>x.id===itemId);if(s.status!=='active'&&plan().limit&&activeStudents().length>=plan().limit){toast('Llegaste al límite de alumnos activos de tu plan.');return;}s.status=s.status==='active'?'inactive':'active';save();render();toast(s.status==='active'?'Alumno reactivado.':'Alumno inactivo. Su historial se conserva.');return;}
if(a==='my-profile')return navigate('Perfil');
if(a==='edit-coach-profile')return coachProfileForm();
if(a==='new-notice')return noticeForm('students');
if(a==='new-admin-notice')return noticeForm('coaches');
if(a==='read-coach-notices'){state.readCoachNotices=state.coachNotices.map(n=>n.id);save();render();toast('Notificaciones marcadas como leídas.');return;}
if(a==='confirm-broadcast'){
 const pending=window.pendingBroadcast;if(!pending)return;
 const list=pending.audience==='students'?state.notices:state.coachNotices;
 list.unshift({id:id(),title:pending.title,body:pending.body,date:today()});
 delete window.pendingBroadcast;save();modal.close();render();toast('Aviso publicado en la prueba local.');return;
}

if(a==='select-plan'){const p=plans.find(x=>x.id===itemId);if(p.limit&&activeStudents().length>p.limit){toast('Tenés más alumnos activos que los permitidos en ese plan.');return;}state.coach.plan=itemId;const c=state.adminCoaches.find(x=>x.id==='c1');if(c)c.plan=itemId;save();render();toast('Plan de prueba actualizado. No se realizó ningún cobro.');return;}
if(a==='start-workout'){ensureDraft(itemId);save();return navigate('Mi rutina',itemId);}if(a==='toggle-exercise'){const d=ensureDraft(b.dataset.rid);const n=Number(b.dataset.index);d.done=d.done.includes(n)?d.done.filter(x=>x!==n):[...d.done,n];save();const scroll=window.scrollY;render();window.scrollTo(0,scroll);return;}if(a==='rest')return startTimer(Number(b.dataset.seconds));if(a==='stop-rest')return stopTimer();if(a==='finish-workout'){const r=state.routines.find(x=>x.id===itemId);const d=ensureDraft(itemId);if(!r||!r.exercises.every((_,i)=>d.done.includes(i)))return;state.sessions.unshift({id:id(),studentId,routineId:r.id,routineName:r.name,date:today(),completedAt:new Date().toISOString(),note:d.note,exercises:r.exercises.map((x,i)=>({...x,name:getExercise(x.exerciseId)?.name||'Ejercicio',load:d.logs[i]?.load??'',actualReps:d.logs[i]?.actualReps??''}))});delete state.drafts[draftKey(studentId,itemId)];save();stopTimer();navigate('Progreso');toast('¡Entrenamiento guardado! Un paso más.');return;}
if(a==='admin-plans')return navigate('Planes');if(a==='admin-coaches')return navigate('Profesores');if(a==='new-coach')return coachForm();if(a==='edit-coach')return coachForm(state.adminCoaches.find(x=>x.id===itemId));if(a==='coach-name')return openModal('Nombre del profesor','Perfil de prueba.',`<form id="coach-name-form">${field('Nombre','name',state.coach.name,'text','required maxlength="80"')}${actions('Guardar')}</form>`);
if(a==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='Entrenar_copia_'+today()+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Copia de seguridad descargada.');return;}if(a==='import')return $('#import-file').click();if(a==='reset')return confirmModal('¿Restablecer la prueba?','Se reemplazarán tus datos locales por los ejemplos iniciales. Podés exportar una copia antes.','confirm-reset');if(a==='confirm-reset'){state=seed();save();studentId='s1';stopTimer();modal.close();render();toast('Prueba restablecida.');return;}
if(a==='install-help')return openModal('Entrenar, siempre a mano','Instalala desde el navegador de tu dispositivo.',`<div class="stack"><div><h3>iPhone · Safari</h3><p class="note-text">Abrí el enlace de Entrenar en Safari. Tocá Compartir y elegí “Agregar a pantalla de inicio”.</p></div><div><h3>Android · Chrome</h3><p class="note-text">Abrí el menú ⋮ y elegí “Instalar aplicación” o “Agregar a pantalla principal”.</p></div><div><h3>PC · Chrome o Edge</h3><p class="note-text">Usá el ícono de instalación de la barra de direcciones o la opción de instalar desde el menú del navegador.</p></div><div class="subtle">Después de la primera carga, la app puede abrirse sin conexión. Los datos de esta prueba se guardan en este navegador y dispositivo.</div></div>`);
});
document.addEventListener('click',e=>{const menu=$('.mobile-more');if(menu?.open&&!menu.contains(e.target))menu.open=false;});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.mobile-more[open],.days-picker[open]').forEach(x=>x.open=false);});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='student-search'){search=t.value;renderStudentList();}if(t.id==='exercise-search'){search=t.value;renderExerciseList();}if(t.dataset.log){const d=ensureDraft(t.dataset.rid);const n=t.dataset.index;if(!d.logs[n])d.logs[n]={};d.logs[n][t.dataset.log]=t.value;save();}if(t.id==='workout-note'){ensureDraft(t.dataset.rid).note=t.value;save();}});
document.addEventListener('change',async e=>{const t=e.target;if(t.name==='days'&&t.closest('.days-picker')){const chosen=[...t.closest('.days-picker').querySelectorAll('input:checked')].map(x=>x.value.slice(0,3));$('#days-summary').textContent=chosen.join(' · ')||'Seleccioná los días';}if(t.id==='role'||t.id==='mobile-role'||t.id==='profile-role'){role=t.value;page=role==='admin'?'Resumen':'Inicio';detailId=null;search='';render();window.scrollTo(0,0);}if(t.id==='student-select'){studentId=t.value;detailId=null;render();}if(t.id==='student-filter'){filter=t.value;renderStudentList();}if(t.id==='import-file'&&t.files[0]){try{if(t.files[0].size>5*1024*1024)throw Error('La copia supera el tamaño permitido (5 MB).');const next=JSON.parse(await t.files[0].text());validateImport(next);window.pendingImport=next;confirmModal('Importar copia de seguridad','Se reemplazarán los datos guardados en este navegador por los de la copia.','confirm-import');}catch(err){toast(err.message||'La copia no es válida.');}t.value='';}});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="confirm-import"]')){state=window.pendingImport;upgradeState();delete window.pendingImport;save();studentId=state.students[0]?.id||'';stopTimer();modal.close();render();toast('Copia importada.');}});
function validateImport(s){if(s?.coach){for(const f of ['email','whatsapp'])if(s.coach[f]!==undefined&&typeof s.coach[f]!=='string')throw Error('Hay datos de profesor inválidos.');}if(s?.coachNotices!==undefined&&(!Array.isArray(s.coachNotices)||s.coachNotices.some(n=>!n||['id','title','body','date'].some(k=>typeof n[k]!=='string'))))throw Error('Hay comunicados inválidos.');if(s?.readCoachNotices!==undefined&&(!Array.isArray(s.readCoachNotices)||s.readCoachNotices.some(x=>typeof x!=='string')))throw Error('Hay estados de lectura inválidos.');if(!s||s.version!==1||!s.coach||typeof s.coach.name!=='string'||!plans.some(p=>p.id===s.coach.plan))throw Error('No es una copia compatible de Entrenar.');for(const k of ['students','exercises','routines','assignments','sessions','notices','adminCoaches'])if(!Array.isArray(s[k]))throw Error('La copia está incompleta.');if(!s.drafts||typeof s.drafts!=='object'||Array.isArray(s.drafts))throw Error('La copia tiene un formato inválido.');for(const [k,fields]of Object.entries({students:['id','name','goal','email','notes','status'],exercises:['id','name','group','video','notes'],routines:['id','name','description'],assignments:['id','studentId','routineId'],sessions:['id','studentId','routineId','routineName','date','completedAt','note'],notices:['id','title','body','date'],adminCoaches:['id','name','plan','status']})){const ids=new Set();for(const x of s[k]){if(!x||fields.some(f=>typeof x[f]!=='string')||ids.has(x.id))throw Error('Hay registros inválidos en la copia.');ids.add(x.id);}}for(const x of s.students)if((x.whatsapp!==undefined&&typeof x.whatsapp!=='string')||!Number.isInteger(x.days)||x.days<1||x.days>7||!['active','inactive'].includes(x.status))throw Error('Hay alumnos inválidos en la copia.');for(const r of s.routines)if(!Array.isArray(r.days)||r.days.some(x=>typeof x!=='string')||!Array.isArray(r.exercises)||!r.exercises.length||r.exercises.some(x=>!s.exercises.some(e=>e.id===x.exerciseId)||!Number.isInteger(x.sets)||x.sets<1||x.sets>30||typeof x.reps!=='string'||!Number.isFinite(x.rest)||x.rest<0||x.rest>600))throw Error('Hay rutinas inválidas en la copia.');for(const x of s.assignments)if(!s.students.some(a=>a.id===x.studentId)||!s.routines.some(a=>a.id===x.routineId))throw Error('Hay asignaciones inválidas en la copia.');for(const x of s.sessions)if(!s.students.some(a=>a.id===x.studentId)||!Array.isArray(x.exercises)||x.exercises.some(e=>typeof e.name!=='string')||!Number.isFinite(Date.parse(x.completedAt)))throw Error('Hay sesiones inválidas en la copia.');for(const d of Object.values(s.drafts))if(!d||!Array.isArray(d.done)||!d.logs||typeof d.logs!=='object'||typeof d.note!=='string')throw Error('Hay sesiones pendientes inválidas en la copia.');for(const c of s.adminCoaches)if(!plans.some(p=>p.id===c.plan)||!['active','pending','inactive'].includes(c.status))throw Error('Hay profesores inválidos en la copia.');}
document.addEventListener('submit',e=>{const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();const form=new FormData(f);const v=n=>String(form.get(n)||'').trim();const err=message=>{$('#form-error').textContent=message;};const itemId=f.dataset.id;
if(f.id==='broadcast-form'){
 if(!v('title')||!v('body'))return err('Completá el título y el mensaje.');
 const audience=f.dataset.audience;if(!['students','coaches'].includes(audience))return err('Revisá los destinatarios.');
 window.pendingBroadcast={audience,title:v('title'),body:v('body')};
 openModal('Revisar aviso','Confirmá el mensaje antes de publicarlo.',`<div class="review-message"><h3>${esc(v('title'))}</h3><p style="white-space:pre-wrap">${esc(v('body'))}</p></div><p class="note-text">Para todos ${audience==='students'?'tus alumnos':'los profesores'} de esta prueba.</p><div class="form-actions">${btn('Cancelar','close-modal','outline')}${btn('Confirmar publicación','confirm-broadcast','primary')}</div>`);return;
}
else if(f.id==='coach-profile-form'){
 if(!v('name'))return err('Completá tu nombre.');const whatsapp=v('whatsapp')?normalizeWhatsapp(v('whatsapp')):'';
 if(v('whatsapp')&&!whatsapp)return err('Ingresá un WhatsApp válido con código de país.');
 Object.assign(state.coach,{name:v('name'),email:v('email'),whatsapp});const c=state.adminCoaches.find(x=>x.id==='c1');if(c)c.name=v('name');
}
else if(f.id==='student-form'){if(!v('name')||!v('goal'))return err('Completá el nombre y el objetivo.');if(!itemId&&plan().limit&&activeStudents().length>=plan().limit)return err('Llegaste al límite de tu plan. Cambiá de plan o pasá un alumno a inactivo.');const whatsapp=normalizeWhatsapp(v('whatsapp'));if(!whatsapp)return err('Ingresá un WhatsApp válido, con código de país y entre 8 y 15 dígitos.');const data={name:v('name'),email:v('email'),whatsapp,goal:v('goal'),days:Number(v('days')),notes:v('notes')};if(!Number.isInteger(data.days)||data.days<1||data.days>7)return err('Elegí entre 1 y 7 días.');if(itemId)Object.assign(state.students.find(s=>s.id===itemId),data);else state.students.push({id:id(),...data,status:'active'});if(!studentId)studentId=state.students[0].id;}
else if(f.id==='exercise-form'){if(!v('name'))return err('Escribí el nombre del ejercicio.');if(v('video')&&safeUrl(v('video'))==='#')return err('Usá un enlace que empiece con https:// o http://.');const data={name:v('name'),group:v('group'),video:v('video'),notes:v('notes')};if(itemId)Object.assign(getExercise(itemId),data);else state.exercises.push({id:id(),...data});}
else if(f.id==='routine-form'){if(!v('name'))return err('Escribí el nombre de la rutina.');const exercises=[...f.querySelectorAll('.exercise-editor')].map(el=>({exerciseId:el.querySelector('[name=exerciseId]').value,sets:Number(el.querySelector('[name=sets]').value),reps:el.querySelector('[name=reps]').value.trim(),rest:Number(el.querySelector('[name=rest]').value)}));if(!exercises.length||exercises.some(x=>!x.reps||!Number.isInteger(x.sets)||x.sets<1||x.sets>30||x.rest<0||x.rest>600))return err('Revisá las series, repeticiones y descansos.');const days=[...new Set(form.getAll('days').map(String))];if(!days.length)return err('Seleccioná al menos un día de entrenamiento.');const data={name:v('name'),description:v('description'),days,exercises};if(itemId){Object.assign(state.routines.find(r=>r.id===itemId),data);for(const k of Object.keys(state.drafts))if(k.endsWith(':'+itemId))delete state.drafts[k];}else state.routines.push({id:id(),...data});}
else if(f.id==='assign-form'){if(state.assignments.some(a=>a.studentId===v('studentId')&&a.routineId===v('routineId')))return err('Este alumno ya tiene asignada esa rutina.');state.assignments.push({id:id(),studentId:v('studentId'),routineId:v('routineId')});}
else if(f.id==='notice-form'){if(!v('title')||!v('body'))return err('Completá el título y el mensaje.');state.notices.unshift({id:id(),title:v('title'),body:v('body'),date:today()});}
else if(f.id==='coach-name-form'){if(!v('name'))return err('Escribí el nombre.');state.coach.name=v('name');const c=state.adminCoaches.find(c=>c.id==='c1');if(c)c.name=v('name');}
else if(f.id==='coach-form'){if(!v('name'))return err('Escribí el nombre del profesor.');if(itemId==='c1'){const p=plans.find(p=>p.id===v('plan'));if(p.limit&&activeStudents().length>p.limit)return err('Ese plan no alcanza para los alumnos activos del profesor.');state.coach.name=v('name');state.coach.plan=v('plan');}const data={name:v('name'),plan:v('plan'),status:v('status')};if(itemId)Object.assign(state.adminCoaches.find(c=>c.id===itemId),data);else state.adminCoaches.push({id:id(),...data});}
else return;save();modal.close();render();toast(f.id==='assign-form'?'Rutina asignada.':f.id==='notice-form'?'Aviso publicado.':'Cambios guardados.');});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPrompt=e;$('#install').hidden=false;});$('#install').addEventListener('click',async()=>{if(!deferredPrompt)return;await deferredPrompt.prompt();await deferredPrompt.userChoice;deferredPrompt=null;$('#install').hidden=true;});window.addEventListener('appinstalled',()=>{$('#install').hidden=true;toast('Entrenar instalada.');});
if('serviceWorker'in navigator)window.addEventListener('load',()=>{navigator.serviceWorker.register('/sw.js').catch(()=>toast('El modo sin conexión no está disponible en este navegador.'));});
render();if(!storageOK)toast('El navegador no permite guardar datos. Exportá una copia antes de salir.');
